CREATE TYPE "SafetyRestrictionParticipantRole" AS ENUM ('REPORTER','REPORTED_PARTICIPANT');CREATE TYPE "SafetyRestrictionStatus" AS ENUM ('PROPOSED','ACTIVE','REJECTED','REVERSED','EXPIRED');CREATE TYPE "SafetyRestrictionDuration" AS ENUM ('HOURS_24','DAYS_7','DAYS_30');CREATE TYPE "SafetyRestrictionEventType" AS ENUM ('PROPOSED','APPROVED_AND_ACTIVATED','REJECTED','REVERSED','EXPIRED');
CREATE TABLE "SafetyReportRestriction" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"safetyReportId" UUID NOT NULL,"participantRole" "SafetyRestrictionParticipantRole" NOT NULL,"participantId" TEXT NOT NULL,"status" "SafetyRestrictionStatus" NOT NULL DEFAULT 'PROPOSED',"duration" "SafetyRestrictionDuration" NOT NULL,"internalReason" VARCHAR(2000) NOT NULL,"participantExplanation" VARCHAR(1000) NOT NULL,"proposedByAdministratorId" TEXT NOT NULL,"proposedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"approvedByAdministratorId" TEXT,"approvedAt" TIMESTAMPTZ(3),"startsAt" TIMESTAMPTZ(3),"expiresAt" TIMESTAMPTZ(3),"rejectedByAdministratorId" TEXT,"rejectedAt" TIMESTAMPTZ(3),"rejectionReason" VARCHAR(2000),"reversedByAdministratorId" TEXT,"reversedAt" TIMESTAMPTZ(3),"reversalReason" VARCHAR(2000),"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL,CONSTRAINT "SafetyReportRestriction_pkey" PRIMARY KEY("id"));
CREATE TABLE "SafetyReportRestrictionEvent" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"restrictionId" UUID NOT NULL,"eventType" "SafetyRestrictionEventType" NOT NULL,"actorAdministratorId" TEXT,"reason" VARCHAR(2000),"occurredAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SafetyReportRestrictionEvent_pkey" PRIMARY KEY("id"));
CREATE INDEX "SafetyReportRestriction_participantId_status_expiresAt_idx" ON "SafetyReportRestriction"("participantId","status","expiresAt");CREATE INDEX "SafetyReportRestriction_safetyReportId_createdAt_id_idx" ON "SafetyReportRestriction"("safetyReportId","createdAt","id");CREATE INDEX "SafetyReportRestrictionEvent_restrictionId_occurredAt_id_idx" ON "SafetyReportRestrictionEvent"("restrictionId","occurredAt","id");
ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_safetyReportId_fkey" FOREIGN KEY("safetyReportId") REFERENCES "SafetyReport"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_participantId_fkey" FOREIGN KEY("participantId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_proposedByAdministratorId_fkey" FOREIGN KEY("proposedByAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_approvedByAdministratorId_fkey" FOREIGN KEY("approvedByAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_rejectedByAdministratorId_fkey" FOREIGN KEY("rejectedByAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_reversedByAdministratorId_fkey" FOREIGN KEY("reversedByAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SafetyReportRestrictionEvent" ADD CONSTRAINT "SafetyReportRestrictionEvent_restrictionId_fkey" FOREIGN KEY("restrictionId") REFERENCES "SafetyReportRestriction"("id") ON DELETE RESTRICT ON UPDATE CASCADE;ALTER TABLE "SafetyReportRestrictionEvent" ADD CONSTRAINT "SafetyReportRestrictionEvent_actorAdministratorId_fkey" FOREIGN KEY("actorAdministratorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_nonempty_text_check" CHECK (length(btrim("internalReason")) BETWEEN 1 AND 2000 AND length(btrim("participantExplanation")) BETWEEN 1 AND 1000);
ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_separation_check" CHECK ("approvedByAdministratorId" IS NULL OR "approvedByAdministratorId" <> "proposedByAdministratorId");
ALTER TABLE "SafetyReportRestriction" ADD CONSTRAINT "SafetyReportRestriction_effective_time_check" CHECK (("startsAt" IS NULL AND "expiresAt" IS NULL) OR ("startsAt" IS NOT NULL AND "expiresAt" > "startsAt"));
CREATE UNIQUE INDEX "SafetyReportRestriction_one_proposed_side_idx" ON "SafetyReportRestriction"("safetyReportId","participantRole") WHERE "status" = 'PROPOSED';
CREATE OR REPLACE FUNCTION "prevent_safety_restriction_event_mutation"() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Safety restriction events are append-only'; END; $$;
CREATE TRIGGER "SafetyReportRestrictionEvent_append_only_update" BEFORE UPDATE ON "SafetyReportRestrictionEvent" FOR EACH ROW EXECUTE FUNCTION "prevent_safety_restriction_event_mutation"();
CREATE TRIGGER "SafetyReportRestrictionEvent_append_only_delete" BEFORE DELETE ON "SafetyReportRestrictionEvent" FOR EACH ROW EXECUTE FUNCTION "prevent_safety_restriction_event_mutation"();
